import json
n=19; out=[[0]*n for _ in range(n)]
sources=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
markers=[(2,6),(4,6),(3,5),(3,7),(3,13),(4,12),(4,14),(5,13),(9,8),(10,7),(10,9),(11,8),(11,14),(12,13),(12,15),(13,14),(13,3),(14,2),(14,4),(15,3)]
for r,c,v in sources:out[r][c]=v
