orig=[row[:] for row in out]
# Full line projections; at line crossings, use the source center nearest along its axis.
for r in range(n):
 for c in range(n):
  if orig[r][c]!=0: continue
  candidates=[]
  for sr,sc,v in sources:
   if sr==r:candidates.append((abs(c-sc),0,v))
   if sc==c:candidates.append((abs(r-sr),1,v))
  if candidates:
   d=min(x[0] for x in candidates)
   tied=[x for x in candidates if x[0]==d]
   out[r][c]=next((x[2] for x in tied if x[1]==1),tied[0][2])
# Empty plus at (10,8) masks its horizontal and vertical projection, preserving original marks.
for c in range(n):
 if orig[10][c]==0:out[10][c]=0
for r in range(n):
 if orig[r][8]==0:out[r][8]=0
assert len(out)==19 and all(len(row)==19 for row in out)
